"use client";

import { motion } from "framer-motion";
import { Phone, Download } from "lucide-react"; // Added Download icon
import { useLanguage } from "@/context/LanguageContext";
import jsPDF from "jspdf"; // For PDF generation (install via npm install jspdf)
import Footer from "../components/Footer"; // Relative import based on your structure (app/payments/page.tsx → app/components/Footer.tsx)

export default function Payments() {
  const { t } = useLanguage();

  // Banking details data
  const bankingDetails = [
    {
      bank: "Standard Bank",
      account: "052292541",
      branch: "051001",
    },
    {
      bank: "First National Bank (FNB)",
      account: "62195435625",
      branch: "250655",
    },
    {
      bank: "Absa Bank",
      account: "4113729185",
      branch: "632005",
    },
  ];

  // Function to generate and download PDF
  const handleDownloadPDF = () => {
    const doc = new jsPDF();

    // Add logo (replace with your actual logo path/URL; fallback to a generic placeholder)
    const logoUrl = "/images/sibiya-logo.png" || "https://via.placeholder.com/150x50?text=Sibiya+Funerals+Logo"; // Placeholder if no local logo
    doc.addImage(logoUrl, "PNG", 10, 10, 60, 20); // Adjust size/position as needed

    // Add title
    doc.setFontSize(18);
    doc.text("Sibiya Funerals Banking Details", 10, 40);

    // Add details
    doc.setFontSize(12);
    bankingDetails.forEach((detail, index) => {
      doc.text(
        `${detail.bank}: Account ${detail.account}, Branch ${detail.branch}`,
        10,
        50 + index * 10
      );
    });

    // Add footer note
    doc.setFontSize(10);
    doc.text("For inquiries, call 072 700 1800", 10, 80 + bankingDetails.length * 10);

    // Download the PDF
    doc.save("sibiya-funerals-banking-details.pdf");
  };

  return (
    <main className="pt-32 pb-20 bg-slate-900 text-white min-h-screen">
      <div className="max-w-7xl mx-auto px-6">
        <motion.h1
          initial={{ opacity: 0, y: 30 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.8 }}
          className="text-4xl md:text-5xl font-bold text-center mb-16"
        >
          {t("payments")} {/* Assuming 'payments' key exists in translations */}
        </motion.h1>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-8 mb-16">
          {bankingDetails.map((detail, index) => (
            <motion.div
              key={index}
              initial={{ opacity: 0, y: 30 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: index * 0.1, duration: 0.6 }}
              className="bg-slate-800 p-6 rounded-xl shadow-lg border-2 border-green-500 hover:shadow-2xl transition-all duration-300 text-center"
            >
              <h3 className="text-xl font-bold mb-4">{detail.bank}</h3>
              <p className="mb-2">Account: {detail.account}</p>
              <p>Branch Code: {detail.branch}</p>
            </motion.div>
          ))}
        </div>

        <div className="text-center mt-16 mb-20">
          <p className="text-lg mb-6 opacity-90">
            Use these details for payments. For assistance, contact us.
          </p>
          <div className="flex flex-col sm:flex-row justify-center gap-6">
            <a
              href="https://wa.me/27727001800"
              className="inline-flex items-center gap-3 bg-green-600 hover:bg-green-700 text-white font-semibold py-4 px-10 rounded-xl text-lg shadow-xl transition-all hover:scale-105"
            >
              <Phone size={24} />
              Contact Us
            </a>
            <button
              onClick={handleDownloadPDF}
              className="inline-flex items-center gap-3 bg-blue-600 hover:bg-blue-700 text-white font-semibold py-4 px-10 rounded-xl text-lg shadow-xl transition-all hover:scale-105"
            >
              <Download size={24} />
              Download as PDF
            </button>
          </div>
        </div>
      </div>

      <Footer />
    </main>
  );
}